"use strict";(self.webpackChunkgf_site=self.webpackChunkgf_site||[]).push([["1924"],{5226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"v0.1.x(Latest)","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"quickSidebar":[{"type":"link","href":"/quick/overview","label":"Project Overview","docId":"quick/overview","unlisted":false},{"type":"link","href":"/quick/installation","label":"Installation","docId":"quick/installation","unlisted":false},{"type":"link","href":"/quick/your-first-plugin","label":"Your First Plugin","docId":"quick/your-first-plugin","unlisted":false},{"type":"link","href":"/quick/what-is-next","label":"What\'s Next","docId":"quick/What-is-next","unlisted":false}],"docsSidebar":[{"type":"category","label":"Design Principles","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ai-native","label":"AI-Native Design","docId":"docs/concepts/ai-native","unlisted":false},{"type":"link","href":"/docs/modular-design","label":"Modular Design","docId":"docs/concepts/modular-design","unlisted":false},{"type":"link","href":"/docs/spec-driven-development","label":"AI Spec-Driven Development","docId":"docs/concepts/spec-driven-development","unlisted":false}],"href":"/docs/concepts"},{"type":"category","label":"Architecture Overview","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/core-host","label":"Core Host Service","docId":"docs/architecture/core-host","unlisted":false},{"type":"link","href":"/docs/admin-workspace","label":"Management Workspace","docId":"docs/architecture/admin-workspace","unlisted":false},{"type":"link","href":"/docs/plugin-system","label":"Dual-Mode Plugin System","docId":"docs/architecture/plugin-system","unlisted":false},{"type":"link","href":"/docs/distributed-architecture","label":"Native Distributed Architecture","docId":"docs/architecture/distributed-architecture","unlisted":false}],"href":"/docs/architecture"},{"type":"category","label":"Plugin Development","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/source-plugins","label":"Source Plugins","docId":"docs/plugin-development/source-plugins","unlisted":false},{"type":"link","href":"/docs/wasm-plugins","label":"Dynamic Plugins (WASM)","docId":"docs/plugin-development/wasm-plugins","unlisted":false}],"href":"/docs/plugin-development"},{"type":"category","label":"Features","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/configuration","label":"Configuration","docId":"docs/features/configuration","unlisted":false},{"type":"link","href":"/docs/api-reference","label":"API Reference","docId":"docs/features/api-reference","unlisted":false},{"type":"link","href":"/docs/scheduled-tasks","label":"Scheduled Tasks","docId":"docs/features/scheduled-tasks","unlisted":false},{"type":"link","href":"/docs/i18n","label":"Internationalization (i18n)","docId":"docs/features/i18n","unlisted":false}],"href":"/docs/features"}],"communitySidebar":[{"type":"link","href":"/community","label":"Community","docId":"community/community","unlisted":false},{"type":"link","href":"/community/support","label":"Support Us","docId":"community/support","unlisted":false}]},"docs":{"community/community":{"id":"community/community","title":"Community","description":"Official LinaPro community channels \u2014 QQ groups, WeChat, Discord, and GitHub Issues \u2014 with guidance on which channel is best for real-time discussion, reproducible bugs, feature requests, documentation feedback, and plugin development questions.","sidebar":"communitySidebar"},"community/support":{"id":"community/support","title":"Support Us","description":"Practical ways to support the long-term maintenance of LinaPro \u2014 filing reproducible issues, improving documentation, sharing production experiences, participating in community discussions, and donating through official channels once they are available.","sidebar":"communitySidebar"},"docs/architecture/admin-workspace":{"id":"docs/architecture/admin-workspace","title":"Management Workspace","description":"A comprehensive look at lina-vben, the LinaPro default management workspace \u2014 its functional modules, technology stack, and design characteristics, including access control, system settings, job scheduling, extension center, developer center, official plugin extensions, and the dynamic menu injection mechanism.","sidebar":"docsSidebar"},"docs/architecture/architecture":{"id":"docs/architecture/architecture","title":"Architecture Overview","description":"A detailed breakdown of LinaPro architecture \u2014 the responsibilities, runtime relationships, and design principles of the five layers: core host service, management workspace, dual-mode plugin system, AI development workflow, and AI skill system. Understand the layered model, loose-coupling approach, and how each component collaborates to deliver business features.","sidebar":"docsSidebar"},"docs/architecture/core-host":{"id":"docs/architecture/core-host","title":"Core Host Service","description":"A detailed look at lina-core, the LinaPro core host service \u2014 the API layer, business service layer, plugin runtime, governance services (JWT auth, RBAC, operation logs, session management), scheduled task subsystem, i18n runtime, and the stable extension seams and event hook system exposed to plugins.","sidebar":"docsSidebar"},"docs/architecture/distributed-architecture":{"id":"docs/architecture/distributed-architecture","title":"Native Distributed Architecture","description":"How LinaPro natively supports distributed deployment \u2014 single-node vs. cluster mode, Raft-style distributed leader election, node roles and horizontal scaling, permission topology version synchronization, distributed locks and cluster-aware key-value cache, and how to enable cluster mode with zero code changes.","sidebar":"docsSidebar"},"docs/architecture/plugin-system":{"id":"docs/architecture/plugin-system","title":"Dual-Mode Plugin System","description":"A comprehensive look at the LinaPro dual-mode plugin system \u2014 source plugins vs. WASM dynamic plugins, the plugin lifecycle (discover, install, enable, disable, uninstall), isolation mechanisms (database namespace, file namespace, WASM sandbox), the host-plugin boundary rules, and the extension point system.","sidebar":"docsSidebar"},"docs/concepts/ai-native":{"id":"docs/concepts/ai-native","title":"AI-Native Design","description":"A detailed look at LinaPro as an AI-native framework \u2014 what AI-native truly means, how it differs from AI-assisted development, how AI participates in every stage of the development lifecycle, the built-in AI skill system covering backend, frontend, testing, performance auditing, and version management, and why spec-driven development prevents architectural drift over time.","sidebar":"docsSidebar"},"docs/concepts/concepts":{"id":"docs/concepts/concepts","title":"Design Principles","description":"An introduction to the core design principles behind LinaPro \u2014 AI-native design, modular architecture, and AI spec-driven development \u2014 helping developers build the right mental model before going deeper into the framework.","sidebar":"docsSidebar"},"docs/concepts/modular-design":{"id":"docs/concepts/modular-design","title":"Modular Design","description":"An exploration of LinaPro modular design \u2014 how domain-bounded built-in capabilities, first-class plugin system, stable extension seams, and lifecycle-managed modules let developers assemble systems from proven building blocks rather than building everything from scratch.","sidebar":"docsSidebar"},"docs/concepts/spec-driven-development":{"id":"docs/concepts/spec-driven-development","title":"AI Spec-Driven Development","description":"A detailed guide to LinaPro Specification-Driven Development (SDD) and the OpenSpec workflow \u2014 the five-stage development loop (explore, propose, implement, review, archive), the responsibilities of AI and humans at each stage, the OpenSpec directory structure and spec file formats, and how spec anchors and mandatory E2E tests prevent architectural drift.","sidebar":"docsSidebar"},"docs/features/api-reference":{"id":"docs/features/api-reference","title":"API Reference","description":"How LinaPro automatically aggregates host and plugin API documentation \u2014 the OpenAPI endpoint, in-workspace API explorer, the declarative interface definition model, RBAC permission integration, multi-language API doc translation, in-browser debugging, and how to import the spec into Apifox, Postman, and other tools.","sidebar":"docsSidebar"},"docs/features/configuration":{"id":"docs/features/configuration","title":"Configuration","description":"A complete reference for the LinaPro core host service config.yaml \u2014 a fully annotated configuration template covering HTTP server, logging, database, JWT authentication, session management, scheduled tasks, internationalization, cluster deployment, file uploads, and plugin management.","sidebar":"docsSidebar"},"docs/features/features":{"id":"docs/features/features","title":"Features","description":"An overview of LinaPro framework features, covering runtime locale file structure and format, how to add new languages, plugin internationalization resource organization, API documentation multi-language translation, runtime translation cache invalidation, and the frontend language switcher \u2014 everything you need to build a globally accessible multi-language application.","sidebar":"docsSidebar"},"docs/features/i18n":{"id":"docs/features/i18n","title":"Internationalization (i18n)","description":"A complete guide to LinaPro internationalization support \u2014 runtime locale file structure and format, adding new languages, organizing plugin i18n resources, translating API documentation, managing translation cache invalidation, and configuring the frontend language switcher. Everything you need to build a globally accessible multi-language application.","sidebar":"docsSidebar"},"docs/features/scheduled-tasks":{"id":"docs/features/scheduled-tasks","title":"Scheduled Tasks","description":"A detailed guide to the LinaPro scheduled task subsystem, covering cron expression configuration, task types (Go handlers and shell commands), group management, execution logs and error inspection, cluster-mode distributed scheduling with deduplication, and how to register custom cron handlers in source plugins.","sidebar":"docsSidebar"},"docs/plugin-development/plugin-development":{"id":"docs/plugin-development/plugin-development","title":"Plugin Development","description":"An overview of LinaPro dual-mode plugin system design \u2014 when to choose source plugins vs. WASM dynamic plugins, a detailed feature comparison, selection guidance, and the unique value of dynamic plugins for hot-loading, production hotfixes, and commercial distribution.","sidebar":"docsSidebar"},"docs/plugin-development/source-plugins":{"id":"docs/plugin-development/source-plugins","title":"Source Plugins","description":"A complete guide to developing LinaPro source plugins \u2014 directory structure conventions, interface definitions, database and file access isolation, plugin lifecycle hook registration, frontend page integration, menu and permission declarations, and the version upgrade process, with full code examples and best practices.","sidebar":"docsSidebar"},"docs/plugin-development/wasm-plugins":{"id":"docs/plugin-development/wasm-plugins","title":"Dynamic Plugins (WASM)","description":"A complete guide to developing LinaPro WASM dynamic plugins \u2014 directory structure, build process, host service bridge interfaces (runtime, storage, network, data), service permission declarations in the plugin manifest, runtime upload and installation, and the key differences from source plugins.","sidebar":"docsSidebar"},"quick/installation":{"id":"quick/installation","title":"Installation","description":"Get LinaPro up and running in minutes. This guide covers system requirements, the one-command install script for macOS, Linux, and Windows, database initialization, using Claude Code to complete dependency setup, and how to start the service and verify a successful installation.","sidebar":"quickSidebar"},"quick/overview":{"id":"quick/overview","title":"Project Overview","description":"A comprehensive introduction to LinaPro \u2014 its background, architecture, and core capabilities. LinaPro is an AI-native full-stack framework built on Go + Vue 3, featuring a dual-mode plugin system, full RBAC permission management, scheduled task scheduling, live API documentation, a spec-driven OpenSpec development workflow, and a lifecycle-spanning AI skill set for building sustainable, continuously deliverable business systems.","sidebar":"quickSidebar"},"quick/What-is-next":{"id":"quick/What-is-next","title":"What\'s Next","description":"Build a complete article management CRUD source plugin and experience LinaPro\'s AI-native development workflow end to end \u2014 from exploring requirements with OpenSpec, generating a proposal, letting AI drive the entire implementation, verifying the result, to archiving the change. A practical introduction to the framework\'s core AI-native development model.","sidebar":"quickSidebar"},"quick/your-first-plugin":{"id":"quick/your-first-plugin","title":"Your First Plugin","description":"Build a complete article management CRUD source plugin and experience LinaPro\'s AI-native development workflow end to end \u2014 from exploring requirements with OpenSpec, generating a proposal, letting AI drive the full implementation, starting the service to verify functionality, to archiving the change. A hands-on introduction to the framework\'s core AI-native development model.","sidebar":"quickSidebar"}}}}')}}]);